package com.bank.appjoin.repo;

import java.util.*;
import java.util.logging.Logger;

// Redis-like store: point lookup by customer_id, independently cacheable.
public class ProfileRepository {
    private static final Logger log = Logger.getLogger(ProfileRepository.class.getName());
    private final Map<String,String> db = Map.of("CUST-RAJESH","Rajesh Kumar","CUST-PRIYA","Priya Sharma");
    private final Map<String,String> cache = new HashMap<>();

    public String findName(String customerId) {
        if (cache.containsKey(customerId)) { log.fine(() -> "profile cache HIT " + customerId); return cache.get(customerId); }
        log.info(() -> "profile store READ " + customerId);
        String name = db.get(customerId);
        cache.put(customerId, name);   // cache under its own key
        return name;
    }
}
