package com.bank.appjoin.repo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// PostgreSQL-like store: point lookup by account id, cacheable.
public class AccountRepository {
    private static final Logger log = Logger.getLogger(AccountRepository.class.getName());
    private final Map<String,BigDecimal> db = Map.of("SAV2001", new BigDecimal("950000"), "CUR3001", new BigDecimal("300000"));
    private final Map<String,BigDecimal> cache = new HashMap<>();

    public BigDecimal findBalance(String accountId) {
        if (cache.containsKey(accountId)) { log.fine(() -> "account cache HIT " + accountId); return cache.get(accountId); }
        log.info(() -> "account store READ " + accountId);
        BigDecimal bal = db.get(accountId);
        cache.put(accountId, bal);
        return bal;
    }
}
