package com.bank.appjoin.service;

import com.bank.appjoin.repo.*;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

// The application-layer JOIN: fetch each piece by PK, assemble in code.
public class DashboardAggregator {
    private static final Logger log = Logger.getLogger(DashboardAggregator.class.getName());
    private final ProfileRepository profiles;
    private final AccountRepository accounts;
    private final TransactionRepository txns;

    public DashboardAggregator(ProfileRepository p, AccountRepository a, TransactionRepository t) {
        this.profiles = p; this.accounts = a; this.txns = t;
    }

    public String build(String customerId, String accountId) {
        String name = profiles.findName(customerId);     // point lookup 1
        BigDecimal bal = accounts.findBalance(accountId); // point lookup 2
        List<String> recent = txns.recent(accountId);     // point lookup 3
        String result = "Dashboard[" + name + "] balance=Rs." + bal + " recent=" + recent;
        log.info(() -> "assembled " + result);
        return result;
    }
}
