package com.bank.appjoin;

import com.bank.appjoin.repo.*;
import com.bank.appjoin.service.DashboardAggregator;
import java.util.logging.*;

public class AppJoinDemo {
    private static final Logger log = Logger.getLogger(AppJoinDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        DashboardAggregator agg = new DashboardAggregator(
                new ProfileRepository(), new AccountRepository(), new TransactionRepository());

        log.info("First build — cold caches");
        agg.build("CUST-RAJESH", "SAV2001");
        log.info("Second build — profile & account now cache HITs");
        agg.build("CUST-RAJESH", "SAV2001");
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

